package me.arcanebrewery.arcaneBrewery.adapter.bukkit.research;
import me.arcanebrewery.arcaneBrewery.adapter.bukkit.ingredient.TestItems;
import me.arcanebrewery.arcaneBrewery.adapter.bukkit.alchemy.EffectProfileMetadata;
import me.arcanebrewery.arcaneBrewery.application.research.*;
import me.arcanebrewery.arcaneBrewery.application.alchemy.*;
import org.bukkit.*;
import org.bukkit.inventory.*;
import org.bukkit.persistence.PersistentDataType;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SpecialistWorkTest {
 static SpecialistWork.Work start(ItemStack[] items,SpecialistState state,long now){return SpecialistWork.start(items,state,now,m->TestItems.stack(m,1));}
 static ItemStack prepared(PreparedReagents.Kind k){return PreparedReagents.create(k,m->TestItems.stack(m,1));}
 static ItemStack bottle(){var item=TestItems.water();item.edit(meta->{var p=meta.getPersistentDataContainer();p.set(new NamespacedKey("arcanebrewery","drink_format"),PersistentDataType.INTEGER,4);p.set(new NamespacedKey("arcanebrewery","drink_stage"),PersistentDataType.STRING,"FINISHED");for(String name:List.of("strength","quality","contamination","magical_potency"))p.set(new NamespacedKey("arcanebrewery","drink_"+name),PersistentDataType.DOUBLE,name.equals("quality")?95.0:0.0);p.set(new NamespacedKey("arcanebrewery","drink_fingerprint"),PersistentDataType.STRING,"a".repeat(64));new EffectProfileMetadata("arcanebrewery").write(meta,new EffectProfile(1,EffectCapabilities.STARTER_INFUSER,List.of(new EffectProfile.Entry(ProfileEffect.HASTE,50,1,false),new EffectProfile.Entry(ProfileEffect.HUNGER,15,0,true)),EffectProfile.Safety.SAFE,100));});return item;}
 @Test void allThreePreparedReagentsHaveRealRecipesAndConsumeExactQuantities(){var raw=List.of(Material.REDSTONE,Material.GLOWSTONE_DUST,Material.QUARTZ);var bind=List.of(Material.AMETHYST_SHARD,Material.BLAZE_ROD,Material.HONEYCOMB);for(int i=0;i<3;i++){var input=new ItemStack[9];input[0]=TestItems.stack(raw.get(i),9);input[1]=TestItems.stack(bind.get(i),3);var out=start(input,new SpecialistState(SpecialistType.REAGENT_PROCESSOR,true,0,0),100);assertEquals(5,out.items()[0].getAmount());assertEquals(2,out.items()[1].getAmount());assertEquals(PreparedReagents.Kind.values()[i],PreparedReagents.read(out.items()[2]).orElseThrow());assertEquals(10100,out.state().readyAt());assertEquals(9,input[0].getAmount());}}
 @Test void constructionConsumesOnlyItsDeclaredMaterialsAndCannotRunTwiceForFree(){var input=new ItemStack[9];input[0]=TestItems.stack(Material.IRON_INGOT,5);input[1]=TestItems.stack(Material.COPPER_INGOT,9);var out=start(input,new SpecialistState(SpecialistType.REAGENT_PROCESSOR,false,0,0),0);assertTrue(out.state().built());assertEquals(1,out.items()[0].getAmount());assertEquals(1,out.items()[1].getAmount());assertThrows(IllegalArgumentException.class,()->start(out.items(),out.state(),1));assertEquals(5,input[0].getAmount());}
 @Test void failedAndBusyProcessesNeverMutateInputs(){var input=new ItemStack[9];input[0]=TestItems.stack(Material.REDSTONE,3);input[1]=TestItems.stack(Material.AMETHYST_SHARD,1);assertThrows(IllegalArgumentException.class,()->start(input,new SpecialistState(SpecialistType.REAGENT_PROCESSOR,true,0,0),0));assertEquals(3,input[0].getAmount());assertThrows(IllegalStateException.class,()->start(input,new SpecialistState(SpecialistType.REAGENT_PROCESSOR,true,100,0),0));}
 @Test void preparedIdentityUsesMetadataRatherThanAnvilNames(){var fake=TestItems.stack(Material.PRISMARINE_SHARD,1);fake.edit(m->m.setDisplayName("Prepared duration reagent"));assertTrue(PreparedReagents.read(fake).isEmpty());var real=prepared(PreparedReagents.Kind.DURATION);assertEquals(PreparedReagents.Kind.DURATION,PreparedReagents.read(real).orElseThrow());}
 @Test void profileAndHistoryAreStoredWithoutChangingIdentityOrHistoricalStatistics(){var input=new ItemStack[9];input[0]=bottle();input[1]=prepared(PreparedReagents.Kind.DURATION);var before=input[0].getItemMeta().getPersistentDataContainer();var out=start(input,new SpecialistState(SpecialistType.DURATION_INFUSER,true,0,0),100);assertNull(out.items()[0]);assertNull(out.items()[1]);var meta=out.items()[2].getItemMeta();assertEquals(600,new EffectProfileMetadata("arcanebrewery").read(meta).orElseThrow().effects().getFirst().seconds());assertEquals(before.get(new NamespacedKey("arcanebrewery","drink_fingerprint"),PersistentDataType.STRING),meta.getPersistentDataContainer().get(new NamespacedKey("arcanebrewery","drink_fingerprint"),PersistentDataType.STRING));assertEquals(95.0,meta.getPersistentDataContainer().get(new NamespacedKey("arcanebrewery","drink_quality"),PersistentDataType.DOUBLE));assertTrue(meta.getPersistentDataContainer().get(new NamespacedKey("arcanebrewery","specialist_log_v1"),PersistentDataType.STRING).contains("DURATION_INFUSER"));var retry=new ItemStack[9];retry[0]=out.items()[2].clone();retry[1]=prepared(PreparedReagents.Kind.DURATION);assertThrows(IllegalStateException.class,()->start(retry,new SpecialistState(SpecialistType.DURATION_INFUSER,true,0,0),20000));assertNotNull(retry[1]);}
 @Test void legacyBottleWithoutStoredProfileIsRetained(){var input=new ItemStack[9];input[0]=bottle();var oldMeta=input[0].getItemMeta();oldMeta.getPersistentDataContainer().remove(new NamespacedKey("arcanebrewery","drink_effect_profile"));oldMeta.getPersistentDataContainer().remove(new NamespacedKey("arcanebrewery","drink_effect_profile_format"));input[0].setItemMeta(oldMeta);input[1]=prepared(PreparedReagents.Kind.DURATION);assertThrows(IllegalArgumentException.class,()->start(input,new SpecialistState(SpecialistType.DURATION_INFUSER,true,0,0),0));assertNotNull(input[0]);assertNotNull(input[1]);}
}
